Node<int>? removeNth(Node<int>? head, int n) {
  final dummy = Node(0, head);
  Node<int>? fast = dummy, slow = dummy;
  for (var i = 0; i <= n; i++) {
    fast = fast!.next;
  }
  while (fast != null) {
    fast = fast.next;
    slow = slow!.next;
  }
  slow!.next = slow.next?.next;
  return dummy.next;
}

void main() {
  var h = removeNth(Node(1, Node(2, Node(3))), 3);
  final out = <int>[];
  for (; h != null; h = h.next) {
