class Node<T> {
  T value;
  Node<T>? next;
  Node(this.value, [this.next]);
}

Node<int>? merge(Node<int>? a, Node<int>? b) {
  final dummy = Node(0);
  var tail = dummy;
  while (a != null && b != null) {
    if (a.value <= b.value) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next!;
  }
  tail.next = a ?? b;
  return dummy.next;
}

void main() {
  var h = merge(Node(1, Node(5)), Node(2, Node(3, Node(9))));
  final out = <int>[];
  for (; h != null; h = h.next) {
    out.add(h.value);
  }
  print(out);
}
